import numpy as np
from scipy.optimize import least_squares
def P(p,t): return p[0]+p[1]*t+p[2]*t**2
def f1(p): return P(p[0:3],T)+P(p[3:6],T)*eps**p[6]*np.exp(-p[7]*eps)
def f2(p): return P(p[0:3],T)+P(p[3:6],T)*eps**p[6]-P(p[7:10],T)*eps**p[8]
def f3(p): return P(p[0:3],T)+P(p[3:6],T)*(1-np.exp(-p[6]*eps))*np.exp(-p[7]*eps)
out=[]
for name,f,n in [('pe',f1,8),('tp',f2,10),('sd',f3,8)]:
    best=None
    for s in range(20):
        p0=np.abs(np.random.RandomState(s).randn(n))+0.2
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda p: np.nan_to_num(f(p)-sigma,nan=1e3,posinf=1e3,neginf=-1e3), p0, max_nfev=1500)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: out.append(str(e))
    if best is not None:
        out.append(f"{name} {np.mean((f(best.x)-sigma)**2)/np.var(sigma):.3e} {np.round(best.x,3)}")
print("\n".join(out))

